"""Tests for retry_context module."""

import pytest

from retry_context import RetryContext, retry_call


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

class FlakyCallable:
    """Callable that fails *fail_count* times then returns *result*."""

    def __init__(self, fail_count: int, result: Any = "ok", exc_type: type = ValueError):
        self.fail_count = fail_count
        self.result = result
        self.exc_type = exc_type
        self.call_count = 0

    def __call__(self, *args, **kwargs):
        self.call_count += 1
        if self.call_count <= self.fail_count:
            raise self.exc_type(f"fail #{self.call_count}")
        return self.result


# ---------------------------------------------------------------------------
# RetryContext tests
# ---------------------------------------------------------------------------

class TestRetryContext:
    def test_succeeds_first_try(self):
        fn = FlakyCallable(fail_count=0)
        with RetryContext(fn, max_retries=3) as ctx:
            result = ctx.run()

        assert result == "ok"
        assert ctx.attempts == 1
        assert ctx.last_error is None

    def test_succeeds_after_retries(self):
        fn = FlakyCallable(fail_count=2)
        with RetryContext(fn, max_retries=3) as ctx:
            result = ctx.run()

        assert result == "ok"
        assert ctx.attempts == 3
        assert ctx.last_error is not None  # records last failure

    def test_exhausts_retries_and_suppresses(self):
        fn = FlakyCallable(fail_count=5)
        with RetryContext(fn, max_retries=3) as ctx:
            result = ctx.run()

        # All retries exhausted — exception suppressed, result is None
        assert result is None
        assert ctx.attempts == 4  # 1 initial + 3 retries
        assert isinstance(ctx.last_error, ValueError)

    def test_non_retryable_exception_propagates(self):
        """Exceptions not in retryable_exceptions should propagate."""
        fn = FlakyCallable(fail_count=1, exc_type=TypeError)
        with pytest.raises(TypeError):
            with RetryContext(fn, max_retries=3, retryable_exceptions=ValueError) as ctx:
                ctx.run()

    def test_specific_retryable_exception(self):
        fn = FlakyCallable(fail_count=2, exc_type=ValueError)
        with RetryContext(fn, max_retries=3, retryable_exceptions=ValueError) as ctx:
            result = ctx.run()

        assert result == "ok"
        assert ctx.attempts == 3

    def test_multiple_retryable_types(self):
        fn = FlakyCallable(fail_count=1, exc_type=IOError)
        with RetryContext(fn, max_retries=2, retryable_exceptions=(ValueError, IOError)) as ctx:
            result = ctx.run()

        assert result == "ok"

    def test_passes_args_and_kwargs(self):
        calls = []

        def add(a, b, prefix="sum"):
            calls.append((a, b, prefix))
            return f"{prefix}={a + b}"

        with RetryContext(add, max_retries=0) as ctx:
            result = ctx.run(3, 4, prefix="total")

        assert result == "total=7"
        assert len(calls) == 1

    def test_invalid_max_retries(self):
        with pytest.raises(ValueError, match="max_retries"):
            RetryContext(lambda: None, max_retries=-1)

    def test_invalid_delay(self):
        with pytest.raises(ValueError, match="delay"):
            RetryContext(lambda: None, delay=-1)

    def test_invalid_backoff(self):
        with pytest.raises(ValueError, match="backoff"):
            RetryContext(lambda: None, backoff=0.5)

    def test_context_manager_resets_state_on_reentry(self):
        fn = FlakyCallable(fail_count=1)
        with RetryContext(fn, max_retries=3) as ctx:
            ctx.run()

        assert ctx.attempts == 2

        # Re-enter the context — state should reset
        fn2 = FlakyCallable(fail_count=0)
        with RetryContext(fn2, max_retries=3) as ctx:
            ctx.run()

        assert ctx.attempts == 1
        assert ctx.last_error is None

    def test_delay_and_backoff_are_applied(self):
        """Verify delay/backoff arithmetic (no actual sleeping)."""
        fn = FlakyCallable(fail_count=2)
        ctx = RetryContext(fn, max_retries=3, delay=0.0, backoff=2.0)

        # Just verify the object was constructed; actual sleep is hard to
        # unit-test without mocking time.sleep, which is out of scope here.
        assert ctx._delay == 0.0
        assert ctx._backoff == 2.0


# ---------------------------------------------------------------------------
# retry_call helper tests
# ---------------------------------------------------------------------------

class TestRetryCall:
    def test_returns_result(self):
        fn = FlakyCallable(fail_count=1, result=42)
        assert retry_call(fn, max_retries=3) == 42

    def test_exhausts_retries_returns_none(self):
        fn = FlakyCallable(fail_count=10)
        assert retry_call(fn, max_retries=2) is None

    def test_passes_args(self):
        def greet(name):
            return f"hello {name}"

        assert retry_call(greet, "world", max_retries=0) == "hello world"

    def test_specific_exception_filter(self):
        fn = FlakyCallable(fail_count=1, exc_type=TypeError)
        with pytest.raises(TypeError):
            retry_call(fn, max_retries=3, retryable_exceptions=ValueError)

